/**
 * Compact, replayable recordings. A recording stores the seed and the ordered
 * event log; frames are regenerated by re-simulating with the deterministic
 * engine and every frame is checked against its recorded hash. Browser-safe:
 * no Node imports.
 */
import { applyHold, applyPlacement, createGame, stateHash, stepGravity } from './engine.ts';
import type { GameState, Rotation } from './engine.ts';
import { argmaxChoice } from './contract.ts';
import type { AgentAnswer, AnswerMeta, Decision, DecisionStatus, GameResult, Metrics, Mode, ReplayFrame, RunSummary } from './contract.ts';

export const RECORDING_FORMAT = 'tetris-bench-recording@1';

export interface RecordedDecision {
  /** called */
  c: 0 | 1;
  /** completed */
  k: 0 | 1;
  /** latencyMs */
  l: number;
  /** budgetMs */
  b: number | null;
  /** yAtQuestion */
  yq: number;
  /** yAtDecision */
  yd: number;
  /** preparationMs */
  p: number;
  /** normalised answer */
  a?: AgentAnswer;
  /** costUsd */
  u?: number;
  /** retries */
  rt?: number;
  /** meta */
  m?: AnswerMeta;
  /** reason */
  why?: string;
}

export interface RecordedEvent {
  /** decision tick */
  t: number;
  /** status */
  e: DecisionStatus;
  /** gravity steps applied before the action */
  g: number;
  /** placement applied (placement statuses only) */
  x?: number;
  r?: Rotation;
  /** elapsedMs */
  ms: number;
  /** hash of the state after this tick */
  sh: string;
  d: RecordedDecision;
}

export interface Recording {
  format: typeof RECORDING_FORMAT;
  ruleset: string;
  id: string;
  startedAt: string;
  brain: string;
  seed: string;
  mode: Mode;
  score: number;
  lines: number;
  pieces: number;
  ticks: number;
  outcome: GameResult['outcome'];
  metrics: Metrics;
  initialHash: string;
  events: RecordedEvent[];
}

/** Everything in the index entry that the recording itself carries. */
export type RecordingSummary = Omit<RunSummary, 'artifactSha256'>;

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

function isPlacementStatus(status: DecisionStatus): boolean {
  return status === 'placement' || status === 'placement-late';
}

function recordDecision(decision: Decision): RecordedDecision {
  const recorded: RecordedDecision = {
    c: decision.called ? 1 : 0,
    k: decision.completed ? 1 : 0,
    l: round2(decision.latencyMs),
    b: decision.budgetMs,
    yq: decision.yAtQuestion,
    yd: decision.yAtDecision,
    p: round2(decision.preparationMs),
  };
  if (decision.answer) recorded.a = decision.answer;
  if (decision.costUsd !== undefined) recorded.u = decision.costUsd;
  if (decision.retries !== undefined) recorded.rt = decision.retries;
  if (decision.meta) recorded.m = decision.meta;
  if (decision.reason) recorded.why = decision.reason;
  return recorded;
}

function restoreDecision(event: RecordedEvent, questionHash: string): Decision {
  const d = event.d;
  const decision: Decision = {
    status: event.e,
    called: d.c === 1,
    completed: d.k === 1,
    stateHash: questionHash,
    latencyMs: d.l,
    budgetMs: d.b,
    gravitySteps: event.g,
    yAtQuestion: d.yq,
    yAtDecision: d.yd,
    preparationMs: d.p,
  };
  if (d.a) decision.answer = d.a;
  if (d.u !== undefined) decision.costUsd = d.u;
  if (d.rt !== undefined) decision.retries = d.rt;
  if (d.m) decision.meta = d.m;
  if (d.why) decision.reason = d.why;
  return decision;
}

export function toRecording(game: GameResult): Recording {
  const [first, ...rest] = game.frames;
  if (!first || first.event !== 'start') throw new Error('integrity: the first frame must be the start frame');
  const events = rest.map((frame): RecordedEvent => {
    if (frame.event === 'start' || !frame.decision) throw new Error(`integrity: frame ${frame.tick} has no decision`);
    const event: RecordedEvent = {
      t: frame.tick,
      e: frame.event,
      g: frame.decision.gravitySteps,
      ms: round2(frame.elapsedMs),
      sh: stateHash(frame.state),
      d: recordDecision(frame.decision),
    };
    if (isPlacementStatus(frame.event)) {
      if (!frame.decision.answer) throw new Error(`integrity: placement at tick ${frame.tick} has no answer`);
      const placement = argmaxChoice(frame.decision.answer.choice);
      event.x = placement.x;
      event.r = placement.rotation;
    }
    return event;
  });
  return {
    format: RECORDING_FORMAT,
    ruleset: game.ruleset,
    id: game.id,
    startedAt: game.startedAt,
    brain: game.brain,
    seed: game.seed,
    mode: game.mode,
    score: game.score,
    lines: game.lines,
    pieces: game.pieces,
    ticks: game.ticks,
    outcome: game.outcome,
    metrics: game.metrics,
    initialHash: stateHash(first.state),
    events,
  };
}

/** Re-simulate one event: gravity steps, then the action, then the tick. */
function replayEvent(state: GameState, event: RecordedEvent): GameState {
  let next = state;
  for (let step = 0; step < event.g; step++) next = stepGravity(next);
  if (isPlacementStatus(event.e)) {
    if (event.x === undefined || event.r === undefined) throw new Error(`integrity: placement at tick ${event.t} has no coordinates`);
    const placed = applyPlacement(next, { x: event.x, rotation: event.r });
    if (placed === next) throw new Error(`integrity: placement at tick ${event.t} is not reachable`);
    next = placed;
  } else if (event.e === 'hold') {
    const held = applyHold(next);
    if (held === next) throw new Error(`integrity: hold at tick ${event.t} is not allowed`);
    next = held;
  }
  return { ...next, tick: event.t };
}

/** Regenerate every frame from the seed and the event log; throws `integrity: …` on any hash mismatch. */
export function expandRecording(rec: Recording): ReplayFrame[] {
  if (rec.format !== RECORDING_FORMAT) throw new Error(`integrity: unsupported format ${rec.format}`);
  let state = createGame(rec.seed);
  if (rec.ruleset !== state.ruleset) throw new Error(`integrity: recording ruleset ${rec.ruleset} is not ${state.ruleset}`);
  if (stateHash(state) !== rec.initialHash) throw new Error('integrity: initial state hash mismatch');
  const frames: ReplayFrame[] = [{ tick: 0, elapsedMs: 0, state, event: 'start' }];
  for (const event of rec.events) {
    const questionHash = stateHash(state);
    state = replayEvent(state, event);
    const hash = stateHash(state);
    if (hash !== event.sh) throw new Error(`integrity: state hash mismatch at tick ${event.t} (${hash} != ${event.sh})`);
    frames.push({ tick: event.t, elapsedMs: event.ms, state, event: event.e, decision: restoreDecision(event, questionHash) });
  }
  const final = frames[frames.length - 1].state;
  if (final.score !== rec.score || final.lines !== rec.lines || final.pieces !== rec.pieces || final.tick !== rec.ticks) {
    throw new Error('integrity: final state does not match the recorded totals');
  }
  return frames;
}

export function fromRecording(rec: Recording): GameResult {
  return {
    id: rec.id,
    ruleset: rec.ruleset,
    startedAt: rec.startedAt,
    brain: rec.brain,
    seed: rec.seed,
    mode: rec.mode,
    score: rec.score,
    lines: rec.lines,
    pieces: rec.pieces,
    ticks: rec.ticks,
    outcome: rec.outcome,
    metrics: rec.metrics,
    frames: expandRecording(rec),
  };
}

/** The index entry for a recording: everything but the events (and the digest, which only the runner knows). */
export function summaryOf(rec: Recording): RecordingSummary {
  return {
    id: rec.id,
    ruleset: rec.ruleset,
    format: rec.format,
    brain: rec.brain,
    seed: rec.seed,
    mode: rec.mode,
    score: rec.score,
    lines: rec.lines,
    pieces: rec.pieces,
    ticks: rec.ticks,
    outcome: rec.outcome,
    startedAt: rec.startedAt,
    metrics: rec.metrics,
  };
}
